"""Malformed generated bytes keep exact native prefixes and exclude only unsafe spans."""
import hashlib
import math
from types import SimpleNamespace

import pytest
import torch
from transformers import AutoTokenizer

from steer_opd.compass_alignment import ByteLevelCodec, INVALID_UTF8_POLICY, VERBATIM_RESPONSE_POLICY, align_response
from steer_opd.resumable_core import ROOT, read_json
from steer_opd.training.losses import distillation_loss, training_alignment
from steer_opd.training.overlap_monitor import row_statistics, summarize_statistics
from steer_opd.training.scoring_request import read_full_request, read_native_request, write_request
from steer_opd.training.verl_adapter import attach_advantages
from test_compass_alignment import ToyCodec


def codecs():
    values = {1:b'a', 2:b'\xe4', 3:b'\xb8', 4:b'b', 5:b'\xff', 6:b'c', 7:b'\xad', 8:b'a\xffb'}
    student = ToyCodec({0:b'<eos>', **values})
    teacher = ToyCodec({0:b'<eos>', **{key+10:value for key,value in values.items() if key!=8}})
    return student, teacher


@pytest.mark.parametrize('tokens,mask,bad_bytes', [
    ([1,5,4,0], [True,False,True,False], 1),
    ([1,2,3,4,0], [True,False,False,True,False], 2),
    ([1,2,3,0], [True,False,False,False], 2),
    ([8,6,0], [False,True,False], 1),
    ([5,0], [False,False], 1),
])
def test_malformed_middle_tail_and_merged_tokens_keep_exact_native_bytes(tokens,mask,bad_bytes):
    s,t = codecs()
    plan = training_alignment(tokens,s,t)
    raw = s.bytes(tokens[:-1])
    assert plan['source_token_ids']==tokens
    assert plan['native_response_ids']['student']==tokens[:-1]
    assert t.bytes(plan['native_response_ids']['teacher'])==raw
    assert plan['response_utf8_sha256']==hashlib.sha256(raw).hexdigest()
    assert plan['alignment_mask']==mask
    assert plan['invalid_utf8']['bytes']==bad_bytes
    assert plan['invalid_utf8']['policy']==INVALID_UTF8_POLICY
    assert plan['invalid_utf8']['response_text_format']=='backslash_escaped_display_only'
    assert any(u['reason']=='invalid_utf8_in_span' for u in plan['units'])
    assert '\ufffd' not in plan['response_text']


def test_valid_utf8_and_static_rejection_keep_original_behavior():
    s,t = codecs()
    tokens=[1,2,3,7,4,0]
    assert training_alignment(tokens,s,t)==align_response(tokens,s,{'teacher':t})
    with pytest.raises(UnicodeDecodeError):
        align_response([1,5,4,0],s,{'teacher':t})
    with pytest.raises(ValueError,match='invalid_utf8'):
        align_response(tokens,s,{'teacher':t},invalid_utf8='replace')
    missing=ToyCodec({0:b'<eos>',11:b'a',14:b'b'})
    with pytest.raises(ValueError,match='cannot preserve'):
        training_alignment([1,5,4,0],s,missing)


def test_invalid_byte_logprobs_are_excluded_and_later_valid_tokens_keep_gradients():
    s,t=codecs();plan=training_alignment([1,2,3,4,0],s,t)
    student=torch.tensor([-1.,float('nan'),float('nan'),-2.,float('nan')],requires_grad=True)
    teacher=torch.tensor([-.5,float('nan'),float('nan'),-1.],requires_grad=True)
    loss=distillation_loss(plan,student,teacher)
    assert loss.valid_tokens==2 and loss.loss.item()==pytest.approx(1.25)
    loss.loss.backward()
    torch.testing.assert_close(student.grad,torch.tensor([-.25,0.,0.,-.5,0.]))
    assert teacher.grad is None


def test_malformed_alignment_survives_lossless_scorer_request_roundtrip(tmp_path):
    s,t=codecs();tokens=[1,2,3,4,0];plan=training_alignment(tokens,s,t)
    native={'teacher':{'id':'r','key':'r','prompt_token_ids':[11],
                       'token_ids':plan['native_response_ids']['teacher']}}
    request={'plan_binding':'utf8_fixed','seed':42,'rows':[{
        'source':{'id':'r','question_id':'q','question':'x?','prompt_token_ids':[1],'token_ids':tokens},
        'alignment':plan,'native':native}]}
    marker=write_request(tmp_path,request)
    restored=read_full_request(tmp_path,marker['request_id'],'utf8_fixed')
    assert restored==request
    _,rows=read_native_request(tmp_path,marker['request_id'],'utf8_fixed','teacher')
    assert t.bytes(rows[0]['token_ids'])==s.bytes(tokens[:-1])


def test_entirely_malformed_trajectory_does_not_abort_a_healthy_batch():
    s,t=codecs();tokens=[[5,0],[1,4,0]]
    replies=[{'alignment':training_alignment(v,s,t),'teacher_logps':torch.full((len(v)-1,),-.5)} for v in tokens]
    responses=torch.tensor([[5,0,0],[1,4,0]])
    batch=SimpleNamespace(meta_info={},batch={
        'responses':responses.clone(),'prompts':torch.tensor([[1],[1]]),
        'attention_mask':torch.tensor([[1,1,1,0],[1,1,1,1]]),
        'response_mask':torch.tensor([[1,1,0],[1,1,1]]),
        'rollout_log_probs':torch.full((2,3),-1.)})
    attach_advantages(batch,replies)
    assert torch.equal(batch.batch['responses'],responses)
    assert batch.batch['response_mask'].tolist()==[[0,0,0],[1,1,0]]
    assert batch.batch['advantages'][0].count_nonzero()==0
    assert batch.meta_info['steer_opd_valid_tokens']==2


def test_overlap_reports_mask_coverage_and_invalid_bytes_without_replacement():
    codec=ToyCodec({0:b'<eos>',**{i+1:bytes([i]) for i in range(256)}})
    tokens=[ord('a')+1,256,ord('b')+1,0]
    alignment=training_alignment(tokens,codec,codec)
    def record(n):
        return {'ids':torch.arange(1,17,dtype=torch.int32)[None,:].repeat(n,1),
                'logps':torch.full((n,16),-math.log(32)),
                'sampled_logps':torch.full((n,),-math.log(32))}
    part=row_statistics({'id':'r','question_id':'q','token_ids':tokens},alignment,
                        record(4),record(3),{'student':codec,'teacher':codec})
    stats=summarize_statistics([part])
    assert stats['overlap/coverage']==.5
    assert stats['overlap/token_value']==1.
    assert stats['P_overlap/token_value']==pytest.approx(.5)
    assert stats['alignment/invalid_utf8_bytes']==1
    assert stats['alignment/invalid_utf8_trajectories']==1


@pytest.fixture(scope='module')
def real_codecs():
    cfg=read_json(ROOT/'configs/ablation.json')
    return {role:ByteLevelCodec(AutoTokenizer.from_pretrained(ROOT/path,local_files_only=True))
            for role,path in cfg['tokenizer_paths'].items()}


@pytest.mark.parametrize('bad', [b'\xe4\xb8',b'\xff',b'\xc0\xaf',b'\xed\xa0\x80'])
def test_real_qwen_student_teacher_keep_all_bytes_and_recover_valid_suffix(real_codecs,bad):
    s,t=real_codecs['student'],real_codecs['teacher']
    single={v:k for k,v in s.raw.items() if len(v)==1 and k not in s.special}
    before=s.encode('Let x = 2. ');after=s.encode(' Then x+1=3. 中文')
    tokens=before+[single[bytes([v])] for v in bad]+after+[s.tokenizer.eos_token_id]
    plan=training_alignment(tokens,s,t)
    raw=s.bytes(tokens[:-1])
    assert t.bytes(plan['native_response_ids']['teacher'])==raw
    assert plan['native_response_ids']['student']==tokens[:-1]
    assert plan['invalid_utf8']['bytes']==len(bad)
    assert any(plan['alignment_mask'][:len(before)])
    assert any(plan['alignment_mask'][-len(after)-1:-1])
    assert not any(plan['alignment_mask'][len(before):len(before)+len(bad)])


def raw_student_ids(codec, raw):
    single={value:token for token,value in codec.raw.items() if len(value)==1 and token not in codec.special}
    return [single[bytes([byte])] for byte in raw]+[codec.tokenizer.eos_token_id]


@pytest.mark.parametrize('text', [
    'Let Cafe\u0301 = 2.',
    'x = A\u030a + 1.',
    'a\u0308\u0301 then b.',
    'x = \u212b; y = \u2126.',
    'a\u0315\u0300 then z.',
])
def test_real_qwen_normalization_preserves_generated_bytes_and_original_tokenizer(real_codecs,text):
    s,t=real_codecs['student'],real_codecs['teacher']
    original=t.tokenizer.backend_tokenizer.to_str()
    raw=text.encode('utf-8');tokens=raw_student_ids(s,raw)
    assert t.bytes(t.encode(text))!=raw  # Reproduce the previous failure with actual assets.
    with pytest.raises(ValueError,match='teacher retokenization'):
        align_response(tokens,s,{'teacher':t})  # Static default stays strict.
    with pytest.raises(ValueError,match='teacher retokenization'):
        align_response(tokens,s,{'teacher':t},invalid_utf8='mask',response_encoding='strict')
    plan=training_alignment(tokens,s,t)
    assert plan['source_token_ids']==tokens and plan['native_response_ids']['student']==tokens[:-1]
    assert t.bytes(plan['native_response_ids']['teacher'])==raw
    assert plan['response_text']==text
    assert plan['alignment_mask']==[True]*(len(tokens)-1)+[False]
    assert 'invalid_utf8' not in plan
    assert plan['verbatim_response_encoding']=={'policy':VERBATIM_RESPONSE_POLICY,'roles':['teacher']}
    assert t.tokenizer.backend_tokenizer.to_str()==original
    backend=t._verbatim_backend
    assert training_alignment(tokens,s,t)==plan and t._verbatim_backend is backend


def test_normalization_and_malformed_bytes_share_exact_native_scorer_prefix(real_codecs):
    s,t=real_codecs['student'],real_codecs['teacher']
    before='Cafe\u0301 '.encode();after=' a\u0308 then z.'.encode()
    raw=before+b'\xff'+after;tokens=raw_student_ids(s,raw)
    plan=training_alignment(tokens,s,t)
    assert t.bytes(plan['native_response_ids']['teacher'])==raw
    assert plan['invalid_utf8']['bytes']==1 and plan['verbatim_response_encoding']['roles']==['teacher']
    assert not plan['alignment_mask'][len(before)]
    assert any(plan['alignment_mask'][len(before)+1:-1])


def test_verbatim_alignment_roundtrip_and_gradients_keep_same_generated_text(real_codecs,tmp_path):
    s,t=real_codecs['student'],real_codecs['teacher']
    raw='Cafe\u0301 = A\u030a.'.encode();tokens=raw_student_ids(s,raw);plan=training_alignment(tokens,s,t)
    source={'id':'r','question_id':'q','question':'x?','prompt_token_ids':[1],'token_ids':tokens}
    native={'teacher':{'id':'r','key':'r','prompt_token_ids':[1],'token_ids':plan['native_response_ids']['teacher']}}
    request={'plan_binding':'verbatim','seed':42,'rows':[{'source':source,'alignment':plan,'native':native}]}
    marker=write_request(tmp_path,request)
    assert read_full_request(tmp_path,marker['request_id'],'verbatim')==request
    _,rows=read_native_request(tmp_path,marker['request_id'],'verbatim','teacher')
    assert t.bytes(rows[0]['token_ids'])==raw
    student=torch.full((len(tokens),),-1.,requires_grad=True)
    teacher=torch.full((len(native['teacher']['token_ids']),),-.5,requires_grad=True)
    result=distillation_loss(plan,student,teacher)
    assert result.valid_tokens==len(tokens)-1
    result.loss.backward()
    torch.testing.assert_close(student.grad[:-1],torch.full((len(tokens)-1,),-.5/(len(tokens)-1)))
    assert student.grad[-1]==0 and teacher.grad is None


def test_verbatim_encoding_keeps_the_final_byte_integrity_guard(real_codecs,monkeypatch):
    s,t=real_codecs['student'],real_codecs['teacher']
    tokens=raw_student_ids(s,'Cafe\u0301'.encode())
    monkeypatch.setattr(t,'encode_verbatim',t.encode)
    with pytest.raises(ValueError,match='teacher retokenization'):
        training_alignment(tokens,s,t)
